-- 01_stage_and_preview.sql
-- Correcao retroativa dos snapshots de 2026-08-14
-- Fonte: aba 'Extração  - Base final diagnóst' (fresh, visivel) do arquivo 6ce0d2f5-13_08_2026_2.xlsx
-- SigmaK (sum licencas) esperado: 58052 | Sigma engajadas esperado: 41356 | IDs unicos: 3959
-- Este script NAO escreve na tabela real. Apenas cria staging + previews.

CREATE TABLE IF NOT EXISTS stg_snapshot_20260814 (
  accountancy_id text,
  licencas numeric,
  licencas_engajadas numeric,
  estoque numeric,
  percentual_engajamento numeric,
  penetracao numeric,
  cnpjs numeric,
  cnpjs_livres numeric,
  contas_potencial numeric,
  ratio numeric,
  plano text,
  atribuidas numeric,
  percentual_atribuidas numeric
);

TRUNCATE stg_snapshot_20260814;









-- ===== PREVIEWS (nao escrevem em partner_snapshots) =====
-- Estado ATUAL na tabela real para 2026-08-14:
SELECT count(*) AS linhas, sum(licencas) AS soma_licencas, sum(licencas_engajadas) AS soma_engajadas
FROM partner_snapshots WHERE imported_at::date='2026-08-14';

-- Estado do STAGING (o que sera aplicado):
SELECT count(*) AS linhas, sum(licencas) AS soma_licencas, sum(licencas_engajadas) AS soma_engajadas
FROM stg_snapshot_20260814;

-- UNMATCHED: accountancy_ids no staging sem parceiro correspondente (nao entrarao no apply):
SELECT s.accountancy_id FROM stg_snapshot_20260814 s
LEFT JOIN partners p ON trim(p.accountancy_id::text)=trim(s.accountancy_id)
WHERE p.id IS NULL;

-- Contagem de unmatched:
SELECT count(*) AS unmatched FROM stg_snapshot_20260814 s
LEFT JOIN partners p ON trim(p.accountancy_id::text)=trim(s.accountancy_id)
WHERE p.id IS NULL;
